"""Regenerate docs/rules.md from the rule catalogue: python tools/gen_docs.py"""

import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "skills" / "leakage-audit" / "scripts"))

from unleak import report, rules  # noqa: E402


def render() -> str:
    out = [
        "# Rules",
        "",
        "<!-- generated by tools/gen_docs.py from unleak/rules.py; do not edit by hand -->",
        "",
        "`unleak check` runs the **UL** rules on code; `unleak data` runs the **UD** checks on a real",
        "train/test pair. `unleak explain <RULE>` prints any section below in the terminal.",
        "",
        "Severity: **error** = supervised information from evaluation rows reaches training, expect",
        "materially inflated metrics; **warning** = methodologically wrong, effect ranges from tiny to",
        "large; **info** = needs a data check to confirm (hidden unless `--min-severity info`).",
        "",
        report.rules_table("markdown").rstrip(),
        "",
    ]
    for r in rules.RULES.values():
        out += [
            f"## {r.id} {r.name}",
            "",
            f"**{r.title}** · severity: `{r.severity}`",
            "",
            r.why,
            "",
            f"**Fix:** {r.fix}",
            "",
            "```python",
            "# leaky",
            r.bad,
            "",
            "# fixed",
            r.good,
            "```",
            "",
        ]
    out.append("Suppress a deliberate case with `# unleak: ignore[RULE]` on the reported line, "
               "or a whole file with `# unleak: skip-file`.")
    return "\n".join(out) + "\n"


if __name__ == "__main__":
    (ROOT / "docs" / "rules.md").write_text(render())
    print("wrote docs/rules.md")
